content.arguments:
{"command":"$p='D:\tmp\mino-sdk\papers\p2.md'; $c=Get-Content -Raw -Encoding UTF8 $p
# Insert newline after period/question/exclamation followed by space, and after long runs
$c2 = $c -replace '(?<=[\.\!\?])\s+', "`n"
# also break very long paragraphs further by splitting on '; ' when line > 400
$lines = $c2 -split "`n"
$out = New-Object System.Collections.Generic.List[string]
foreach($l in $lines){
  if($l.Length -gt 500){
    $words = $l -split ' '
    $cur = ''
    foreach($w in $words){
      if(($cur.Length + $w.Length + 1) -gt 220){ $out.Add($cur.Trim()); $cur = $w }
      else { if($cur -eq ''){$cur=$w} else {$cur = $cur + ' ' + $w} }
    }
    if($cur.Trim().Length -gt 0){$out.Add($cur.Trim())}
  } else { $out.Add($l) }
}
$out -join "`n" | Set-Content -Encoding UTF8 'D:\tmp\mino-sdk\papers\p2_wrapped.md'
Write-Output ("lines: " + $out.Count)","description":"Wrap paper into readable lines"}

